type histogram_t = [0..<256] uint;
record SharedHistogram
{
 var bins: histogram_t;
 var locks: [0..<256] sync int;

 proc reset()
 {
 for i in 0..<bins.size
 {
 lock locks[i] do
 bins[i] = 0;
 }
 }

 proc increment(value: uint(8))
 {
 lock locks[value] do
 bins[value] += 1;
 }

 proc snapshot(): histogram_t
 {
 var copy: histogram_t;
 for i in 0..<bins.size
 {
 lock locks[i] do
 copy[i] = bins[i];
 }
 return copy;
 }
};
