record SimpleMatrix {
 type GO = int;
 type SC = real;

 var rows: [] GO; // global row ids stored locally
 var row_indices: [] [] GO; // per-row sorted column indices
 var row_coefs: [] [] SC; // per-row coefficients

 // find local index for a global row id; return -1 if not present
 proc find_row_idx(row: GO): int {
 var it = rows.binarySearch(row);
 if it == rows.size || rows[it] != row then return -1;
 return it;
 }
};
record LockingMatrix {
 var matrix_: SimpleMatrix;
 // per-row array of per-entry locks
 var row_locks_: [] [] sync int;

 proc init(matrix: SimpleMatrix)
 {
 matrix_ = matrix;
 // allocate per-entry locks to match matrix_.row_indices shape
 row_locks_ = new [0..<matrix_.row_indices.size] [] sync int;
 for r in 0..<matrix_.row_indices.size {
 var cols = matrix_.row_indices[r].size;
 row_locks_[r] = new [0..<cols] sync int;
 }
 }
};
